  color: var(--text-primary);
  letter-spacing: -1px;
}

.stats-banner .stat-desc {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}

.page-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border: 1px solid var(--border-color);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}

.page-btn:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.page-btn.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Candlestick chart SVG */
.candle-green { fill: var(--positive); }
.candle-red { fill: var(--negative); }
.wick { stroke-width: 1; }
.wick-green { stroke: var(--positive); }
.wick-red { stroke: var(--negative); }

/* Market summary cards horizontal scroll */
.market-summary-row {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.market-summary-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 14px 18px;
  min-width: 200px;
  flex-shrink: 0;
}

.market-summary-card .index-name {
  font-size: 0.72rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.market-summary-card .index-price {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.market-summary-card .index-change {
  font-size: 0.78rem;
  font-weight: 600;
}

/* Earnings table */
.earnings-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.earnings-beat { background: var(--positive-bg); color: var(--positive); }
.earnings-miss { background: var(--negative-bg); color: var(--negative); }

/* Indicator/strategy listing */
.indicator-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-light);
}

.indicator-item:last-child { border-bottom: none; }

.indicator-icon {
  width: 40px;
  height: 40px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  flex-shrink: 0;
}

.indicator-info { flex: 1; min-width: 0; }
.indicator-name { font-weight: 600; font-size: 0.85rem; margin-bottom: 2px; }
.indicator-author { font-size: 0.72rem; color: var(--text-muted); }
.indicator-likes { font-size: 0.78rem; color: var(--text-secondary); font-weight: 500; }

/* Responsive chart workspace */
@media (max-width: 1200px) {
  .chart-workspace {
    grid-template-columns: 220px 1fr 280px;
  }
}

@media (max-width: 900px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
    height: auto;
  }
  .watchlist-sidebar { display: none; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border-color); }
}

/* News card */
.news-card {
  display: flex;
  gap: 16px;
  padding: 16px 0;
  border-bottom: 1px solid var(--border-light);
}

.news-card:last-child { border-bottom: none; }

.news-thumb {
  width: 120px;
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  flex-shrink: 0;
}

.news-title {
  font-weight: 600;
  font-size: 0.88rem;
  margin-bottom: 6px;
  line-height: 1.4;
}

.news-source {
  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Volume bars */
.volume-bar {
  height: 4px;
  border-radius: 2px;
  background: var(--border-color);
  position: relative;
  overflow: hidden;
}

.volume-bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 2px;
}

/* Yield curve line */
.yield-display {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.yield-rate {
  font-size: 1.5rem;
  font-weight: 800;
}

/* Tab group JS helper */
.tab-panel { display: none; }
.tab-panel.active { display: block; }
