tool_use_result.content:
/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0a0a14;
  --bg-secondary: #12121e;
  --bg-tertiary: #1a1a2e;
  --bg-card: #16162a;
  --bg-hover: #1e1e36;
  --bg-input: #1a1a30;
  --border-color: #2a2a45;
  --border-light: #1e1e38;
  --text-primary: #e8e8f0;
  --text-secondary: #9898b0;
  --text-muted: #6a6a85;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fd6;
  --accent-teal: #26a69a;
  --positive: #26a69a;
  --positive-bg: rgba(38,166,154,0.12);
  --negative: #ef5350;
  --negative-bg: rgba(239,83,80,0.12);
  --gold: #f0b90b;
  --platinum: #a0a0c0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; transition: color 0.2s; }
a:hover { color: #5b8aff; }

/* Layout */
.container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.container-fluid { padding: 0 24px; }

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  height: 56px;
  display: flex;
  align-items: center;
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-left { display: flex; align-items: center; gap: 32px; }

.logo {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  letter-spacing: -0.5px;
}

.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent-blue);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}

.nav-links { display: flex; gap: 4px; }

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  transition: all 0.2s;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.nav-right { display: flex; align-items: center; gap: 12px; }

.nav-search {
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 7px 14px;
  color: var(--text-secondary);
  font-size: 0.8rem;
  width: 220px;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.2s;
  font-family: var(--font);
}

.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-outline { background: transparent; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-outline:hover { border-color: var(--text-secondary); background: var(--bg-hover); }
.btn-sm { padding: 5px 12px; font-size: 0.78rem; }
.btn-ghost { background: transparent; color: var(--text-secondary); padding: 6px 10px; }
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Market Ticker Bar */
.ticker-bar {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-light);
  padding: 8px 0;
  overflow-x: auto;
  white-space: nowrap;
}

.ticker-bar::-webkit-scrollbar { height: 0; }

.ticker-items {
  display: flex;
  gap: 28px;
  padding: 0 24px;
  font-size: 0.78rem;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ticker-item .name { color: var(--text-secondary); font-weight: 500; }
.ticker-item .price { color: var(--text-primary); font-weight: 600; }
.ticker-item .change { font-weight: 600; }

.change-positive { color: var(--positive); }
.change-negative { color: var(--negative); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 20px;
  overflow-x: auto;
}

.tabs::-webkit-scrollbar { height: 0; }

.tab {
  padding: 10px 18px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: var(--font);
}

.tab:hover { color: var(--text-primary); }
.tab.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }

.pill-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.pill-tab {
  padding: 6px 16px;
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: var(--font);
}

.pill-tab:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.pill-tab.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 20px;
  transition: border-color 0.2s;
}

.card:hover { border-color: #3a3a55; }

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.card-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}

.data-table td {
  padding: 10px 12px;
  font-size: 0.82rem;
  border-bottom: 1px solid var(--border-light);
}

.data-table tr:hover { background: var(--bg-hover); }

.data-table .text-right { text-align: right; }
.data-table .ticker { font-weight: 600; color: var(--accent-blue); }
.data-table .company { color: var(--text-secondary); font-size: 0.75rem; }

/* Sparkline placeholder */
.sparkline {
  width: 80px;
  height: 32px;
  display: inline-block;
  vertical-align: middle;
}

.sparkline svg { width: 100%; height: 100%; }

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: rgba(150,150,180,0.12); color: var(--text-secondary); }

.badge-platinum { background: rgba(160,160,192,0.15); color: var(--platinum); border: 1px solid rgba(160,160,192,0.2); }
.badge-gold { background: rgba(240,185,11,0.12); color: var(--gold); border: 1px solid rgba(240,185,11,0.2); }

/* Section */
.section { padding: 40px 0; }
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* Grid */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero-title {
  font-size: 3rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}

.hero-actions { display: flex; gap: 12px; justify-content: center; }

/* Stat card */
.stat-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label { font-size: 0.72rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
.stat-value { font-size: 1.15rem; font-weight: 700; }
.stat-change { font-size: 0.78rem; font-weight: 600; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 0 24px;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.78rem;
  padding: 3px 0;
  transition: color 0.2s;
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Toggle switch */
.toggle {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  cursor: pointer;
  border: 1px solid var(--border-color);
  transition: background 0.2s;
}

.toggle.active { background: var(--accent-blue); border-color: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 50%;
  top: 1px;
  left: 1px;
  transition: transform 0.2s;
}
.toggle.active::after { transform: translateX(16px); }

/* Rating stars */
.stars { color: var(--gold); font-size: 0.82rem; letter-spacing: 1px; }

/* Idea card */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}

.idea-card:hover { border-color: #3a3a55; transform: translateY(-2px); }

.idea-chart {
  height: 180px;
  background: var(--bg-tertiary);
  position: relative;
  overflow: hidden;
}

.idea-body { padding: 16px; }

.idea-title { font-weight: 600; font-size: 0.88rem; margin-bottom: 6px; line-height: 1.4; }

.idea-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.72rem;
  color: var(--text-muted);
}

.idea-author {
  display: flex;
  align-items: center;
  gap: 6px;
}

.avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.idea-stats {
  display: flex;
  gap: 12px;
  margin-left: auto;
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* Responsive */
@media (max-width: 1024px) {
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .container { padding: 0 16px; }
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .hero-title { font-size: 2rem; }
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .section { padding: 24px 0; }
}

/* Tab content visibility */
.tab-content { display: none; }
.tab-content.active { display: block; }

/* Utility */
.text-positive { color: var(--positive); }
.text-negative { color: var(--negative); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }
.fw-600 { font-weight: 600; }
.fw-700 { font-weight: 700; }
.flex { display: flex; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mt-24 { margin-top: 24px; }
.p-16 { padding: 16px; }
.p-20 { padding: 20px; }

/* Broker Card */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: border-color 0.2s;
}

.broker-card:hover { border-color: #3a3a55; }

.broker-logo {
  width: 56px;
  height: 56px;
  background: var(--bg-tertiary);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.7rem;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.broker-info { flex: 1; min-width: 0; }
.broker-name { font-weight: 700; font-size: 1rem; margin-bottom: 4px; }
.broker-meta { font-size: 0.78rem; color: var(--text-secondary); display: flex; gap: 16px; align-items: center; }
.broker-rating { font-weight: 700; color: var(--gold); }
.broker-promo {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  color: var(--accent-blue);
  padding: 6px 14px;
  border-radius: 8px;
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
}

/* Chart workspace specific */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}

.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
}

.watchlist-header {
  padding: 16px;
  font-weight: 700;
  font-size: 0.88rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-group-header {
  padding: 10px 16px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--bg-primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-light);
  user-select: none;
}

.watchlist-group-header:hover { background: var(--bg-hover); }

.watchlist-group-header .arrow {
  transition: transform 0.2s;
  font-size: 0.65rem;
}

.watchlist-group-header.collapsed .arrow { transform: rotate(-90deg); }

.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 8px;
  padding: 8px 16px;
  font-size: 0.8rem;
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  align-items: center;
}

.watchlist-item:hover { background: var(--bg-hover); }
.watchlist-item.active { background: rgba(41,98,255,0.1); border-left: 2px solid var(--accent-blue); }
.watchlist-item .symbol { font-weight: 600; }
.watchlist-item .last-price { text-align: right; font-weight: 500; }
.watchlist-item .change-pct { text-align: right; font-weight: 600; font-size: 0.75rem; }

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
  flex-wrap: wrap;
}

.chart-toolbar .symbol-display {
  font-weight: 700;
  font-size: 1rem;
  margin-right: 8px;
}

.timeframe-btn {
  padding: 4px 10px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: none;
  border: 1px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.15s;
}

.timeframe-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.timeframe-btn.active { color: var(--accent-blue); background: rgba(41,98,255,0.1); border-color: rgba(41,98,255,0.3); }

.chart-area {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}

.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}

.detail-section {
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
}

.detail-section h3 {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  padding: 5px 0;
  font-size: 0.8rem;
}

.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 600; text-align: right; }

/* Stats banner */
.stats-banner {
  background: linear-gradient(135deg, #1a1a3e 0%, #12122a 100%);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  text-align: center;
  margin: 40px 0;
}

.stats-banner .stat-number {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -1px;
}

.stats-banner .stat-desc {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}

.page-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border: 1px solid var(--border-color);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}

.page-btn:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.page-btn.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Candlestick chart SVG */
.candle-green { fill: var(--positive); }
.candle-red { fill: var(--negative); }
.wick { stroke-width: 1; }
.wick-green { stroke: var(--positive); }
.wick-red { stroke: var(--negative); }

/* Market summary cards horizontal scroll */
.market-summary-row {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.market-summary-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 14px 18px;
  min-width: 200px;
  flex-shrink: 0;
}

.market-summary-card .index-name {
  font-size: 0.72rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.market-summary-card .index-price {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.market-summary-card .index-change {
  font-size: 0.78rem;
  font-weight: 600;
}

/* Earnings table */
.earnings-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.earnings-beat { background: var(--positive-bg); color: var(--positive); }
.earnings-miss { background: var(--negative-bg); color: var(--negative); }

/* Indicator/strategy listing */
.indicator-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-light);
}

.indicator-item:last-child { border-bottom: none; }

.indicator-icon {
  width: 40px;
  height: 40px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  flex-shrink: 0;
}

.indicator-info { flex: 1; min-width: 0; }
.indicator-name { font-weight: 600; font-size: 0.85rem; margin-bottom: 2px; }
.indicator-author { font-size: 0.72rem; color: var(--text-muted); }
.indicator-likes { font-size: 0.78rem; color: var(--text-secondary); font-weight: 500; }

/* Responsive chart workspace */
@media (max-width: 1200px) {
  .chart-workspace {
    grid-template-columns: 220px 1fr 280px;
  }
}

@media (max-width: 900px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
    height: auto;
  }
  .watchlist-sidebar { display: none; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border-color); }
}

/* News card */
.news-card {
  display: flex;
  gap: 16px;
  padding: 16px 0;
  border-bottom: 1px solid var(--border-light);
}

.news-card:last-child { border-bottom: none; }

.news-thumb {
  width: 120px;
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  flex-shrink: 0;
}

.news-title {
  font-weight: 600;
  font-size: 0.88rem;
  margin-bottom: 6px;
  line-height: 1.4;
}

.news-source {
  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Volume bars */
.volume-bar {
  height: 4px;
  border-radius: 2px;
  background: var(--border-color);
  position: relative;
  overflow: hidden;
}

.volume-bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 2px;
}

/* Yield curve line */
.yield-display {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.yield-rate {
  font-size: 1.5rem;
  font-weight: 800;
}

/* Tab group JS helper */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0a0a14;
  --bg-secondary: #12121e;
  --bg-tertiary: #1a1a2e;
  --bg-card: #16162a;
  --bg-hover: #1e1e36;
  --bg-input: #1a1a30;
  --border-color: #2a2a45;
  --border-light: #1e1e38;
  --text-primary: #e8e8f0;
  --text-secondary: #9898b0;
  --text-muted: #6a6a85;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fd6;
  --accent-teal: #26a69a;
  --positive: #26a69a;
  --positive-bg: rgba(38,166,154,0.12);
  --negative: #ef5350;
  --negative-bg: rgba(239,83,80,0.12);
  --gold: #f0b90b;
  --platinum: #a0a0c0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; transition: color 0.2s; }
a:hover { color: #5b8aff; }

/* Layout */
.container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.container-fluid { padding: 0 24px; }

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  height: 56px;
  display: flex;
  align-items: center;
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-left { display: flex; align-items: center; gap: 32px; }

.logo {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  letter-spacing: -0.5px;
}

.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent-blue);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}

.nav-links { display: flex; gap: 4px; }

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  transition: all 0.2s;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.nav-right { display: flex; align-items: center; gap: 12px; }

.nav-search {
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 7px 14px;
  color: var(--text-secondary);
  font-size: 0.8rem;
  width: 220px;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.2s;
  font-family: var(--font);
}

.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-outline { background: transparent; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-outline:hover { border-color: var(--text-secondary); background: var(--bg-hover); }
.btn-sm { padding: 5px 12px; font-size: 0.78rem; }
.btn-ghost { background: transparent; color: var(--text-secondary); padding: 6px 10px; }
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Market Ticker Bar */
.ticker-bar {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-light);
  padding: 8px 0;
  overflow-x: auto;
  white-space: nowrap;
}

.ticker-bar::-webkit-scrollbar { height: 0; }

.ticker-items {
  display: flex;
  gap: 28px;
  padding: 0 24px;
  font-size: 0.78rem;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ticker-item .name { color: var(--text-secondary); font-weight: 500; }
.ticker-item .price { color: var(--text-primary); font-weight: 600; }
.ticker-item .change { font-weight: 600; }

.change-positive { color: var(--positive); }
.change-negative { color: var(--negative); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 20px;
  overflow-x: auto;
}

.tabs::-webkit-scrollbar { height: 0; }

.tab {
  padding: 10px 18px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: var(--font);
}

.tab:hover { color: var(--text-primary); }
.tab.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }

.pill-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.pill-tab {
  padding: 6px 16px;
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: var(--font);
}

.pill-tab:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.pill-tab.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 20px;
  transition: border-color 0.2s;
}

.card:hover { border-color: #3a3a55; }

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.card-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}

.data-table td {
  padding: 10px 12px;
  font-size: 0.82rem;
  border-bottom: 1px solid var(--border-light);
}

.data-table tr:hover { background: var(--bg-hover); }

.data-table .text-right { text-align: right; }
.data-table .ticker { font-weight: 600; color: var(--accent-blue); }
.data-table .company { color: var(--text-secondary); font-size: 0.75rem; }

/* Sparkline placeholder */
.sparkline {
  width: 80px;
  height: 32px;
  display: inline-block;
  vertical-align: middle;
}

.sparkline svg { width: 100%; height: 100%; }

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: rgba(150,150,180,0.12); color: var(--text-secondary); }

.badge-platinum { background: rgba(160,160,192,0.15); color: var(--platinum); border: 1px solid rgba(160,160,192,0.2); }
.badge-gold { background: rgba(240,185,11,0.12); color: var(--gold); border: 1px solid rgba(240,185,11,0.2); }

/* Section */
.section { padding: 40px 0; }
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* Grid */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero-title {
  font-size: 3rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}

.hero-actions { display: flex; gap: 12px; justify-content: center; }

/* Stat card */
.stat-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label { font-size: 0.72rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
.stat-value { font-size: 1.15rem; font-weight: 700; }
.stat-change { font-size: 0.78rem; font-weight: 600; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 0 24px;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.78rem;
  padding: 3px 0;
  transition: color 0.2s;
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Toggle switch */
.toggle {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  cursor: pointer;
  border: 1px solid var(--border-color);
  transition: background 0.2s;
}

.toggle.active { background: var(--accent-blue); border-color: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 50%;
  top: 1px;
  left: 1px;
  transition: transform 0.2s;
}
.toggle.active::after { transform: translateX(16px); }

/* Rating stars */
.stars { color: var(--gold); font-size: 0.82rem; letter-spacing: 1px; }

/* Idea card */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}

.idea-card:hover { border-color: #3a3a55; transform: translateY(-2px); }

.idea-chart {
  height: 180px;
  background: var(--bg-tertiary);
  position: relative;
  overflow: hidden;
}

.idea-body { padding: 16px; }

.idea-title { font-weight: 600; font-size: 0.88rem; margin-bottom: 6px; line-height: 1.4; }

.idea-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.72rem;
  color: var(--text-muted);
}

.idea-author {
  display: flex;
  align-items: center;
  gap: 6px;
}

.avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.idea-stats {
  display: flex;
  gap: 12px;
  margin-left: auto;
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* Responsive */
@media (max-width: 1024px) {
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .container { padding: 0 16px; }
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .hero-title { font-size: 2rem; }
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .section { padding: 24px 0; }
}

/* Tab content visibility */
.tab-content { display: none; }
.tab-content.active { display: block; }

/* Utility */
.text-positive { color: var(--positive); }
.text-negative { color: var(--negative); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }
.fw-600 { font-weight: 600; }
.fw-700 { font-weight: 700; }
.flex { display: flex; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mt-24 { margin-top: 24px; }
.p-16 { padding: 16px; }
.p-20 { padding: 20px; }

/* Broker Card */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: border-color 0.2s;
}

.broker-card:hover { border-color: #3a3a55; }

.broker-logo {
  width: 56px;
  height: 56px;
  background: var(--bg-tertiary);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.7rem;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.broker-info { flex: 1; min-width: 0; }
.broker-name { font-weight: 700; font-size: 1rem; margin-bottom: 4px; }
.broker-meta { font-size: 0.78rem; color: var(--text-secondary); display: flex; gap: 16px; align-items: center; }
.broker-rating { font-weight: 700; color: var(--gold); }
.broker-promo {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  color: var(--accent-blue);
  padding: 6px 14px;
  border-radius: 8px;
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
}

/* Chart workspace specific */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}

.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
}

.watchlist-header {
  padding: 16px;
  font-weight: 700;
  font-size: 0.88rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-group-header {
  padding: 10px 16px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--bg-primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-light);
  user-select: none;
}

.watchlist-group-header:hover { background: var(--bg-hover); }

.watchlist-group-header .arrow {
  transition: transform 0.2s;
  font-size: 0.65rem;
}

.watchlist-group-header.collapsed .arrow { transform: rotate(-90deg); }

.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 8px;
  padding: 8px 16px;
  font-size: 0.8rem;
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  align-items: center;
}

.watchlist-item:hover { background: var(--bg-hover); }
.watchlist-item.active { background: rgba(41,98,255,0.1); border-left: 2px solid var(--accent-blue); }
.watchlist-item .symbol { font-weight: 600; }
.watchlist-item .last-price { text-align: right; font-weight: 500; }
.watchlist-item .change-pct { text-align: right; font-weight: 600; font-size: 0.75rem; }

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
  flex-wrap: wrap;
}

.chart-toolbar .symbol-display {
  font-weight: 700;
  font-size: 1rem;
  margin-right: 8px;
}

.timeframe-btn {
  padding: 4px 10px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: none;
  border: 1px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.15s;
}

.timeframe-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.timeframe-btn.active { color: var(--accent-blue); background: rgba(41,98,255,0.1); border-color: rgba(41,98,255,0.3); }

.chart-area {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}

.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}

.detail-section {
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
}

.detail-section h3 {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  padding: 5px 0;
  font-size: 0.8rem;
}

.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 600; text-align: right; }

/* Stats banner */
.stats-banner {
  background: linear-gradient(135deg, #1a1a3e 0%, #12122a 100%);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  text-align: center;
  margin: 40px 0;
}

.stats-banner .stat-number {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -1px;
}

.stats-banner .stat-desc {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}

.page-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border: 1px solid var(--border-color);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}

.page-btn:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.page-btn.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Candlestick chart SVG */
.candle-green { fill: var(--positive); }
.candle-red { fill: var(--negative); }
.wick { stroke-width: 1; }
.wick-green { stroke: var(--positive); }
.wick-red { stroke: var(--negative); }

/* Market summary cards horizontal scroll */
.market-summary-row {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.market-summary-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 14px 18px;
  min-width: 200px;
  flex-shrink: 0;
}

.market-summary-card .index-name {
  font-size: 0.72rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.market-summary-card .index-price {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.market-summary-card .index-change {
  font-size: 0.78rem;
  font-weight: 600;
}

/* Earnings table */
.earnings-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.earnings-beat { background: var(--positive-bg); color: var(--positive); }
.earnings-miss { background: var(--negative-bg); color: var(--negative); }

/* Indicator/strategy listing */
.indicator-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-light);
}

.indicator-item:last-child { border-bottom: none; }

.indicator-icon {
  width: 40px;
  height: 40px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  flex-shrink: 0;
}

.indicator-info { flex: 1; min-width: 0; }
.indicator-name { font-weight: 600; font-size: 0.85rem; margin-bottom: 2px; }
.indicator-author { font-size: 0.72rem; color: var(--text-muted); }
.indicator-likes { font-size: 0.78rem; color: var(--text-secondary); font-weight: 500; }

/* Responsive chart workspace */
@media (max-width: 1200px) {
  .chart-workspace {
    grid-template-columns: 220px 1fr 280px;
  }
}

@media (max-width: 900px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
    height: auto;
  }
  .watchlist-sidebar { display: none; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border-color); }
}

/* News card */
.news-card {
  display: flex;
  gap: 16px;
  padding: 16px 0;
  border-bottom: 1px solid var(--border-light);
}

.news-card:last-child { border-bottom: none; }

.news-thumb {
  width: 120px;
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  flex-shrink: 0;
}

.news-title {
  font-weight: 600;
  font-size: 0.88rem;
  margin-bottom: 6px;
  line-height: 1.4;
}

.news-source {
  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Volume bars */
.volume-bar {
  height: 4px;
  border-radius: 2px;
  background: var(--border-color);
  position: relative;
  overflow: hidden;
}

.volume-bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 2px;
}

/* Yield curve line */
.yield-display {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.yield-rate {
  font-size: 1.5rem;
  font-weight: 800;
}

/* Tab group JS helper */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

raw_arguments.content:
/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0a0a14;
  --bg-secondary: #12121e;
  --bg-tertiary: #1a1a2e;
  --bg-card: #16162a;
  --bg-hover: #1e1e36;
  --bg-input: #1a1a30;
  --border-color: #2a2a45;
  --border-light: #1e1e38;
  --text-primary: #e8e8f0;
  --text-secondary: #9898b0;
  --text-muted: #6a6a85;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fd6;
  --accent-teal: #26a69a;
  --positive: #26a69a;
  --positive-bg: rgba(38,166,154,0.12);
  --negative: #ef5350;
  --negative-bg: rgba(239,83,80,0.12);
  --gold: #f0b90b;
  --platinum: #a0a0c0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; transition: color 0.2s; }
a:hover { color: #5b8aff; }

/* Layout */
.container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.container-fluid { padding: 0 24px; }

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  height: 56px;
  display: flex;
  align-items: center;
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-left { display: flex; align-items: center; gap: 32px; }

.logo {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  letter-spacing: -0.5px;
}

.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent-blue);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}

.nav-links { display: flex; gap: 4px; }

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  transition: all 0.2s;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.nav-right { display: flex; align-items: center; gap: 12px; }

.nav-search {
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 7px 14px;
  color: var(--text-secondary);
  font-size: 0.8rem;
  width: 220px;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.2s;
  font-family: var(--font);
}

.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-outline { background: transparent; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-outline:hover { border-color: var(--text-secondary); background: var(--bg-hover); }
.btn-sm { padding: 5px 12px; font-size: 0.78rem; }
.btn-ghost { background: transparent; color: var(--text-secondary); padding: 6px 10px; }
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Market Ticker Bar */
.ticker-bar {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-light);
  padding: 8px 0;
  overflow-x: auto;
  white-space: nowrap;
}

.ticker-bar::-webkit-scrollbar { height: 0; }

.ticker-items {
  display: flex;
  gap: 28px;
  padding: 0 24px;
  font-size: 0.78rem;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ticker-item .name { color: var(--text-secondary); font-weight: 500; }
.ticker-item .price { color: var(--text-primary); font-weight: 600; }
.ticker-item .change { font-weight: 600; }

.change-positive { color: var(--positive); }
.change-negative { color: var(--negative); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 20px;
  overflow-x: auto;
}

.tabs::-webkit-scrollbar { height: 0; }

.tab {
  padding: 10px 18px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: var(--font);
}

.tab:hover { color: var(--text-primary); }
.tab.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }

.pill-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.pill-tab {
  padding: 6px 16px;
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: var(--font);
}

.pill-tab:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.pill-tab.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 20px;
  transition: border-color 0.2s;
}

.card:hover { border-color: #3a3a55; }

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.card-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}

.data-table td {
  padding: 10px 12px;
  font-size: 0.82rem;
  border-bottom: 1px solid var(--border-light);
}

.data-table tr:hover { background: var(--bg-hover); }

.data-table .text-right { text-align: right; }
.data-table .ticker { font-weight: 600; color: var(--accent-blue); }
.data-table .company { color: var(--text-secondary); font-size: 0.75rem; }

/* Sparkline placeholder */
.sparkline {
  width: 80px;
  height: 32px;
  display: inline-block;
  vertical-align: middle;
}

.sparkline svg { width: 100%; height: 100%; }

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: rgba(150,150,180,0.12); color: var(--text-secondary); }

.badge-platinum { background: rgba(160,160,192,0.15); color: var(--platinum); border: 1px solid rgba(160,160,192,0.2); }
.badge-gold { background: rgba(240,185,11,0.12); color: var(--gold); border: 1px solid rgba(240,185,11,0.2); }

/* Section */
.section { padding: 40px 0; }
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* Grid */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero-title {
  font-size: 3rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}

.hero-actions { display: flex; gap: 12px; justify-content: center; }

/* Stat card */
.stat-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label { font-size: 0.72rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
.stat-value { font-size: 1.15rem; font-weight: 700; }
.stat-change { font-size: 0.78rem; font-weight: 600; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 0 24px;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.78rem;
  padding: 3px 0;
  transition: color 0.2s;
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Toggle switch */
.toggle {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  cursor: pointer;
  border: 1px solid var(--border-color);
  transition: background 0.2s;
}

.toggle.active { background: var(--accent-blue); border-color: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 50%;
  top: 1px;
  left: 1px;
  transition: transform 0.2s;
}
.toggle.active::after { transform: translateX(16px); }

/* Rating stars */
.stars { color: var(--gold); font-size: 0.82rem; letter-spacing: 1px; }

/* Idea card */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}

.idea-card:hover { border-color: #3a3a55; transform: translateY(-2px); }

.idea-chart {
  height: 180px;
  background: var(--bg-tertiary);
  position: relative;
  overflow: hidden;
}

.idea-body { padding: 16px; }

.idea-title { font-weight: 600; font-size: 0.88rem; margin-bottom: 6px; line-height: 1.4; }

.idea-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.72rem;
  color: var(--text-muted);
}

.idea-author {
  display: flex;
  align-items: center;
  gap: 6px;
}

.avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.idea-stats {
  display: flex;
  gap: 12px;
  margin-left: auto;
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* Responsive */
@media (max-width: 1024px) {
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .container { padding: 0 16px; }
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .hero-title { font-size: 2rem; }
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .section { padding: 24px 0; }
}

/* Tab content visibility */
.tab-content { display: none; }
.tab-content.active { display: block; }

/* Utility */
.text-positive { color: var(--positive); }
.text-negative { color: var(--negative); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }
.fw-600 { font-weight: 600; }
.fw-700 { font-weight: 700; }
.flex { display: flex; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mt-24 { margin-top: 24px; }
.p-16 { padding: 16px; }
.p-20 { padding: 20px; }

/* Broker Card */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: border-color 0.2s;
}

.broker-card:hover { border-color: #3a3a55; }

.broker-logo {
  width: 56px;
  height: 56px;
  background: var(--bg-tertiary);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.7rem;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.broker-info { flex: 1; min-width: 0; }
.broker-name { font-weight: 700; font-size: 1rem; margin-bottom: 4px; }
.broker-meta { font-size: 0.78rem; color: var(--text-secondary); display: flex; gap: 16px; align-items: center; }
.broker-rating { font-weight: 700; color: var(--gold); }
.broker-promo {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  color: var(--accent-blue);
  padding: 6px 14px;
  border-radius: 8px;
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
}

/* Chart workspace specific */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}

.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
}

.watchlist-header {
  padding: 16px;
  font-weight: 700;
  font-size: 0.88rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-group-header {
  padding: 10px 16px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--bg-primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-light);
  user-select: none;
}

.watchlist-group-header:hover { background: var(--bg-hover); }

.watchlist-group-header .arrow {
  transition: transform 0.2s;
  font-size: 0.65rem;
}

.watchlist-group-header.collapsed .arrow { transform: rotate(-90deg); }

.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 8px;
  padding: 8px 16px;
  font-size: 0.8rem;
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  align-items: center;
}

.watchlist-item:hover { background: var(--bg-hover); }
.watchlist-item.active { background: rgba(41,98,255,0.1); border-left: 2px solid var(--accent-blue); }
.watchlist-item .symbol { font-weight: 600; }
.watchlist-item .last-price { text-align: right; font-weight: 500; }
.watchlist-item .change-pct { text-align: right; font-weight: 600; font-size: 0.75rem; }

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
  flex-wrap: wrap;
}

.chart-toolbar .symbol-display {
  font-weight: 700;
  font-size: 1rem;
  margin-right: 8px;
}

.timeframe-btn {
  padding: 4px 10px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: none;
  border: 1px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.15s;
}

.timeframe-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.timeframe-btn.active { color: var(--accent-blue); background: rgba(41,98,255,0.1); border-color: rgba(41,98,255,0.3); }

.chart-area {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}

.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}

.detail-section {
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
}

.detail-section h3 {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  padding: 5px 0;
  font-size: 0.8rem;
}

.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 600; text-align: right; }

/* Stats banner */
.stats-banner {
  background: linear-gradient(135deg, #1a1a3e 0%, #12122a 100%);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  text-align: center;
  margin: 40px 0;
}

.stats-banner .stat-number {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -1px;
}

.stats-banner .stat-desc {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}

.page-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border: 1px solid var(--border-color);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.2s;
}

.page-btn:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.page-btn.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Candlestick chart SVG */
.candle-green { fill: var(--positive); }
.candle-red { fill: var(--negative); }
.wick { stroke-width: 1; }
.wick-green { stroke: var(--positive); }
.wick-red { stroke: var(--negative); }

/* Market summary cards horizontal scroll */
.market-summary-row {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.market-summary-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 14px 18px;
  min-width: 200px;
  flex-shrink: 0;
}

.market-summary-card .index-name {
  font-size: 0.72rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.market-summary-card .index-price {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.market-summary-card .index-change {
  font-size: 0.78rem;
  font-weight: 600;
}

/* Earnings table */
.earnings-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 600;
}

.earnings-beat { background: var(--positive-bg); color: var(--positive); }
.earnings-miss { background: var(--negative-bg); color: var(--negative); }

/* Indicator/strategy listing */
.indicator-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-light);
}

.indicator-item:last-child { border-bottom: none; }

.indicator-icon {
  width: 40px;
  height: 40px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  flex-shrink: 0;
}

.indicator-info { flex: 1; min-width: 0; }
.indicator-name { font-weight: 600; font-size: 0.85rem; margin-bottom: 2px; }
.indicator-author { font-size: 0.72rem; color: var(--text-muted); }
.indicator-likes { font-size: 0.78rem; color: var(--text-secondary); font-weight: 500; }

/* Responsive chart workspace */
@media (max-width: 1200px) {
  .chart-workspace {
    grid-template-columns: 220px 1fr 280px;
  }
}

@media (max-width: 900px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
    height: auto;
  }
  .watchlist-sidebar { display: none; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border-color); }
}

/* News card */
.news-card {
  display: flex;
  gap: 16px;
  padding: 16px 0;
  border-bottom: 1px solid var(--border-light);
}

.news-card:last-child { border-bottom: none; }

.news-thumb {
  width: 120px;
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  flex-shrink: 0;
}

.news-title {
  font-weight: 600;
  font-size: 0.88rem;
  margin-bottom: 6px;
  line-height: 1.4;
}

.news-source {
  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Volume bars */
.volume-bar {
  height: 4px;
  border-radius: 2px;
  background: var(--border-color);
  position: relative;
  overflow: hidden;
}

.volume-bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 2px;
}

/* Yield curve line */
.yield-display {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.yield-rate {
  font-size: 1.5rem;
  font-weight: 800;
}

/* Tab group JS helper */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

